CREATE TABLE _idmig_guild (old_key TEXT PRIMARY KEY, new_id INTEGER NOT NULL UNIQUE);
INSERT INTO _idmig_guild
SELECT slug, 1 * 1000000000 + day * 100000 + ROW_NUMBER() OVER (PARTITION BY day ORDER BY slug)
FROM (SELECT slug, CASE WHEN CAST(created_at AS INTEGER) = 0 THEN 0 ELSE CAST(created_at AS INTEGER) / 86400 - 20454 END AS day FROM tenants);

CREATE TABLE _idmig_user (old_key TEXT PRIMARY KEY, new_id INTEGER NOT NULL UNIQUE);
INSERT INTO _idmig_user
SELECT discord_id, 2 * 1000000000 + day * 100000 + ROW_NUMBER() OVER (PARTITION BY day ORDER BY created_at, discord_id)
FROM (SELECT discord_id, created_at, CASE WHEN CAST(created_at AS INTEGER) = 0 THEN 0 ELSE CAST(created_at AS INTEGER) / 86400 - 20454 END AS day FROM users);

CREATE TABLE _idmig_map_events (old_key TEXT PRIMARY KEY, new_id INTEGER NOT NULL UNIQUE);
INSERT INTO _idmig_map_events
SELECT CAST(id AS TEXT), 10 * 1000000000 + day * 100000 + ROW_NUMBER() OVER (PARTITION BY day ORDER BY id)
FROM (SELECT id, CASE WHEN created_at IS NULL OR created_at = '' THEN 0 ELSE CAST(julianday(created_at) - julianday('2026-01-01') AS INTEGER) END AS day FROM events);

